module.exports = function (RED) {
  "use strict";
  var fs = require("fs-extra");
  var iconv = require("iconv-lite");

  function decode(data, enc) {
    console.log("IN DECODING FUNCTION");
    if (enc !== "none") {
      return iconv.decode(data, enc);
    }
    return data.toString();
  }

  function readFile(msg, node, nodeSend, nodeDone) {
    var filename = (node.filename || msg.filename || "").replace(
      /\t|\r|\n/g,
      ""
    );
    console.log(filename);
    if (!node.filename) {
      node.status({ fill: "grey", shape: "dot", text: filename });
    }
    if (filename === "") {
      node.warn(RED._("file.errors.nofilename"));
      nodeDone();
    } else {
      msg.filename = filename;
      var lines = Buffer.from([]);
      var spare = "";
      var count = 0;
      var type = "buffer";
      var ch = "";
      if (node.format === "lines") {
        ch = "\n";
        type = "string";
      }
      var hwm;
      var getout = false;

      var rs = fs
        .createReadStream(filename)
        .on("readable", function () {
          var chunk;
          var hwm = rs._readableState.highWaterMark;
          while (null !== (chunk = rs.read())) {
            if (node.chunk === true) {
              getout = true;
              if (node.format === "lines") {
                spare += decode(chunk, node.encoding);
                var bits = spare.split("\n");
                for (var i = 0; i < bits.length - 1; i++) {
                  var m = {
                    payload: bits[i],
                    topic: msg.topic,
                    filename: msg.filename,
                    parts: { index: count, ch: ch, type: type, id: msg._msgid },
                  };
                  count += 1;
                  nodeSend(m);
                }
                spare = bits[i];
              }
              if (node.format === "stream") {
                var m = {
                  payload: chunk,
                  topic: msg.topic,
                  filename: msg.filename,
                  parts: { index: count, ch: ch, type: type, id: msg._msgid },
                };
                count += 1;
                if (chunk.length < hwm) {
                  // last chunk is smaller that high water mark = eof
                  getout = false;
                  m.parts.count = count;
                }
                nodeSend(m);
              }
            } else {
              lines = Buffer.concat([lines, chunk]);
            }
          }
        })
        .on("error", function (err) {
          // console.log("ERROR", err);
          node.error(err, msg);
          if (node.sendError) {
            var sendMessage = RED.util.cloneMessage(msg);
            delete sendMessage.payload;
            sendMessage.error = err;
            nodeSend(sendMessage);
          }
          nodeDone();
        })
        .on("end", function () {
          console.log("on end");
          // console.log(node);

          if (node.chunk === false) {
            if (node.format === "utf8") {
              msg.payload = decode(lines, node.encoding);
            } else {
              msg.payload = lines;
            }
            nodeSend(msg);
          } else if (node.format === "lines") {
            var m = {
              payload: spare,
              topic: msg.topic,
              parts: {
                index: count,
                count: count + 1,
                ch: ch,
                type: type,
                id: msg._msgid,
              },
            };
            nodeSend(m);
          } else if (getout) {
            // last chunk same size as high water mark - have to send empty extra packet.
            var m = {
              parts: {
                index: count,
                count: count,
                ch: ch,
                type: type,
                id: msg._msgid,
              },
            };
            nodeSend(m);
          }
          nodeDone();
        });
    }
  }
  function RatioNode(n) {
    RED.nodes.createNode(this, n);
    this.subject = this.name;
    this.filename = n.filename;
    this.format = n.format;
    this.chunk = false;
    this.encoding = n.encoding || "none";
    if (n.sendError === undefined) {
      this.sendError = true;
    } else {
      this.sendError = n.sendError;
    }
    if (this.format === "lines") {
      this.chunk = true;
    }
    if (this.format === "stream") {
      this.chunk = true;
    }
    var node = this;
    this.on("input", (msg, send, done) => {
      readFile(msg, node, send, done);
    });
  }

  RED.nodes.registerType("ratio", RatioNode);
};
